diff --git a/tests/repro-18575/repro.cjs b/tests/repro-18575/repro.cjs
new file mode 100644
index 0000000..8c64177
--- /dev/null
+++ b/tests/repro-18575/repro.cjs
@@ -0,0 +1,47 @@
+/*
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ * Run with: node -r ./tests/repro-18575/simulate-win32.cjs tests/repro-18575/repro.cjs
+ */
+"use strict";
+const path = require("node:path");
+const { Linter, ESLint } = require("../../lib/api");
+
+const cwd = process.cwd(); // C:\Project (simulated)
+const code = "foo();\n";
+const rules = { "no-undef": "error" };
+const cases = [
+    ["F:\\foo.js", "different drive (reported)"],
+    ["C:\\other\\foo.js", "same drive, outside cwd (control)"]
+];
+
+(async () => {
+    console.log(`cwd = ${cwd}`);
+    let failed = false;
+
+    for (const [filePath, label] of cases) {
+        console.log(`\n=== ${filePath}  [${label}]`);
+        console.log(`path.win32.relative(cwd, file) = ${JSON.stringify(path.win32.relative(cwd, filePath))}`);
+
+        const linter = new Linter({ configType: "flat", cwd });
+        const linterMsgs = linter.verify(code, { rules }, filePath);
+
+        console.log(`Linter#verify: ${JSON.stringify(linterMsgs.map(m => m.ruleId ? `${m.ruleId}: ${m.message}` : m.message))}`);
+
+        const eslint = new ESLint({ cwd, overrideConfigFile: true, overrideConfig: { rules } });
+        const ignored = await eslint.isPathIgnored(filePath);
+        const [result] = await eslint.lintText(code, { filePath, warnIgnored: true });
+
+        console.log(`ESLint#isPathIgnored: ${ignored}`);
+        console.log(`ESLint#lintText: ${JSON.stringify(result.messages.map(m => m.ruleId ? `${m.ruleId}: ${m.message}` : m.message))}`);
+
+        const linted = linterMsgs.some(m => m.ruleId === "no-undef") || !ignored;
+
+        if (linted) {
+            failed = true;
+            console.log("-> BUG: file outside the base path was linted instead of ignored");
+        } else {
+            console.log("-> OK: file is ignored");
+        }
+    }
+    process.exitCode = failed ? 1 : 0;
+})();
diff --git a/tests/repro-18575/simulate-win32.cjs b/tests/repro-18575/simulate-win32.cjs
new file mode 100644
index 0000000..e66423b
--- /dev/null
+++ b/tests/repro-18575/simulate-win32.cjs
@@ -0,0 +1,29 @@
+/*
+ * Preload (`node -r`) that simulates Windows path semantics on a non-Windows host.
+ * Only ESLint's own modules and @eslint/config-array get `path.win32`; Node internals
+ * and the real file system are untouched (ESLint's own "C:\\..." module URLs are mapped
+ * back to host paths). process.cwd() reports a C: drive directory.
+ */
+"use strict";
+const Module = require("node:module");
+const path = require("node:path");
+
+const repoRoot = path.resolve(__dirname, "../..");
+const simulated = [path.join(repoRoot, "lib") + path.sep, path.join(repoRoot, "node_modules", "@eslint", "config-array") + path.sep];
+const originalLoad = Module._load;
+
+Module._load = function(request, parent, ...rest) {
+    if ((request === "path" || request === "node:path") && parent && simulated.some(dir => parent.filename.startsWith(dir))) {
+        return path.win32;
+    }
+    if ((request === "url" || request === "node:url") && parent && simulated.some(dir => parent.filename.startsWith(dir))) {
+        const url = originalLoad.call(this, request, parent, ...rest);
+
+        // ESLint's own files (e.g. the formatter) are resolved to "C:\\home\\..." under win32 path rules; map them back to the real host path.
+        return { ...url, pathToFileURL: p => url.pathToFileURL(/^C:\\/u.test(p) ? p.slice(2).replace(/\\/gu, "/") : p) };
+    }
+    return originalLoad.call(this, request, parent, ...rest);
+};
+
+process.env.SIMULATED_CWD = process.env.SIMULATED_CWD || "C:\\Project";
+process.cwd = () => process.env.SIMULATED_CWD;
